with cleaned as (select *, lower(device_code) as device_code_lower from device_readings where reading_ts > timestamp '2025-09-01 06:00:00') select case when status_bits >= 9 then 'LARGE' else 'SMALL' end as status_bits_tier, device_code, min(reading_ts) as first_seen, approx_percentile(humidity, array(0.25, 0.5, 0.75)) as humidity_quartiles, percentile_approx(status_bits, 0.95) as status_bits_p95, bit_and(status_bits) as status_bits_bit_and, grouping_id() as grouping_id from cleaned group by cube (case when status_bits >= 9 then 'LARGE' else 'SMALL' end, device_code) order by status_bits_bit_and;
